<?php
namespace App\Foundation\Console;use App\Foundation\Generation\FilePlan;use App\Foundation\Support\JsonFile;use App\Foundation\Support\Names;
final class ModuleRenameCommand extends FoundationCommand{protected $signature='module:rename {from} {to} {--dry-run} {--force}';protected $description='Rename a module manifest and directory when safe.';public function handle(FilePlan $p):int{$f=Names::studly($this->argument('from'));$t=Names::studly($this->argument('to'));$src=base_path("app/Modules/{$f}/module.json");if(!is_file($src)){$this->error('Module not found.');return self::FAILURE;}$m=JsonFile::read($src);$m['name']=$t;$p->write("app/Modules/{$t}/module.json",JsonFile::encode($m));$p->delete("app/Modules/{$f}/module.json");$this->warn('Only the manifest is moved automatically. Move PHP sources deliberately to preserve namespaces.');return $this->runPlan($p,"module:rename {$f} {$t}");}}
